    async def list(self, *, workspace_id: Optional[str] = None, limit: Optional[int] = None, cursor: Optional[str] = None, include_offline: Optional[bool] = None, include_children: Optional[bool] = None, request_options: Optional[RequestOptions] = None) -> _m.ListAgentsResponse:
        """List all agents

        Lists the tenant's agents newest first. `limit` defaults to 20 and is capped at 100,
        `cursor` is the opaque continuation from the previous page, and `has_more` says whether more
        remain. Bridge agents whose machine is not currently connected are omitted unless
        `include_offline=true`, and attribution-only shells are dropped entirely; because those
        filters run after the KV read, the page is refilled round by round until `limit` VISIBLE
        rows are collected, bounded at 500 scanned rows and 20 rounds — when a bound stops the scan
        early `has_more` stays true rather than claiming completeness. Bridge rows are enriched with
        the live machine's capabilities instead of the summary frozen into the record at enrolment.

        `GET /api/v1/agents`

        Required scopes: `agents:read`.
        """
        return _cast("_m.ListAgentsResponse", await self._client._request(
            "GET",
            "/api/v1/agents",
            query=[("workspace_id", workspace_id), ("limit", limit), ("cursor", cursor), ("include_offline", include_offline), ("include_children", include_children)],
            response=_Response(type=_m.ListAgentsResponse),
            request_options=request_options,
        ))

    async def list_all(self, *, workspace_id: Optional[str] = None, limit: Optional[int] = None, cursor: Optional[str] = None, include_offline: Optional[bool] = None, include_children: Optional[bool] = None, request_options: Optional[RequestOptions] = None) -> AsyncIterator[_m.Agent]:
        """Every item `list` returns, following the `cursor` cursor until the server reports no further
        pages. Starts at `cursor` when one is given.
        """
        guard = _CursorGuard()
        while True:
            page = await self.list(workspace_id=workspace_id, limit=limit, cursor=cursor, include_offline=include_offline, include_children=include_children, request_options=request_options)
            items = page.items
            for item in items:
                yield item

            cursor = guard.advance(page.cursor, page.has_more, not items)
            if cursor is None:
                return

